print('order mapping mismatches',mism)
print('shop orders ids >=681 range', s.execute('select min(id),max(id),count(*) from orders where id>=681 and id<=1010').fetchone())
print('orders 1011+ sample', s.execute('select id,number,customer_id,placed_at,status,total,paid_total from orders where id>1010 limit 5').fetchall())
